const pagesByPath = Object.fromEntries(seoLandingPages.map((page) => [page.path, page]))

export function getSeoLandingPages() {
  return seoLandingPages
}

export function getSeoLandingPageByPath(pathname) {
  return pagesByPath[pathname] || null
}

export function getSeoLandingInternalLinks(page) {
  return [
    { path: '/programmes', label: 'All QCTO Accredited Programmes' },
    { path: page.facultyPath, label: page.facultyLabel },
    {
      path: `/programmes/${page.qualificationSlug}`,
      label: 'Full Programme Details',
    },
  ]
}

export function getSeoLandingSitemapPaths() {
  return seoLandingPages.map((page) => page.path)
}
